import { test, expect } from '@playwright/test';

test.describe('Loading States for Assistive Technology', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/data-table');
  });

  test('should communicate loading state to assistive technology when data is being fetched', async ({ page }) => {
    // Intercept the API call to simulate loading
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Click the button to trigger data fetch
    const fetchButton = page.getByRole('button', { name: /fetch data/i });
    await expect(fetchButton).toBeVisible();
    await fetchButton.click();

    // Verify loading spinner is visible
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Verify aria-live region is present and has loading message
    const liveRegion = page.locator('[aria-live="polite"]');
    await expect(liveRegion).toBeVisible();
    await expect(liveRegion).toContainText('Loading data');

    // Verify loading state is announced by screen readers
    const pageContent = page.locator('[data-testid="page-content"]');
    await expect(pageContent).toContainText('Loading data');

    // Wait for loading to complete
    await page.waitForTimeout(1000);

    // Verify loading spinner is no longer visible
    await expect(loadingSpinner).not.toBeVisible();

    // Verify data table is displayed
    const dataTable = page.getByRole('table');
    await expect(dataTable).toBeVisible();
    await expect(dataTable).toContainText('Data loaded successfully');
  });

  test('should handle loading state when API request fails and communicate error to assistive technology', async ({ page }) => {
    // Intercept the API call to simulate failure
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Click the button to trigger data fetch
    const fetchButton = page.getByRole('button', { name: /fetch data/i });
    await expect(fetchButton).toBeVisible();
    await fetchButton.click();

    // Verify loading spinner is visible
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for loading to complete
    await page.waitForTimeout(1000);

    // Verify loading spinner is no longer visible
    await expect(loadingSpinner).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Failed to load data');

    // Verify error message is announced by screen readers
    const liveRegion = page.locator('[aria-live="assertive"]');
    await expect(liveRegion).toBeVisible();
    await expect(liveRegion).toContainText('Error: Failed to load data');

    // Verify data table is not displayed
    const dataTable = page.getByRole('table');
    await expect(dataTable).not.toBeVisible();
  });
});
